/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

/*--------------------------------------------------------------------------*/

void d2d_valet_wake (Wake_Status wake_status)
{
    D2d_Valet_Port *port;
	  port = (D2d_Valet_Port *) smsg_port[d2d_valet_port_no];
    switch(wake_status)
    {
        case s_SLEEP:
        {
			// do nothing , it is already a GPIO pin
        }
        break;

        case s_WAKE:
        {
					port->smsgbase.pre_wake = FALSE;
					if( gpio_pl_int_stat_f( port->butn_pin_label))
						{
							// indebounce state
							d2d_valet_debounce_state = DEBOUNCE_PRESS;
						}
					else if( gpio_pl_int_stat_r( port->butn_pin_label))
						{
							d2d_valet_debounce_state = DEBOUNCE_RELEASE;
						}

			// do nothing it is already a gpio pin
        }
        break;

        default : break ;
    }
}

